-- Every saved word gets a dictionary entry. Meanings are not copied, because they may have been
-- edited by hand and edits stay private to the user.
INSERT INTO "dictionary_entries" ("normalized_term", "term", "part_of_speech")
SELECT DISTINCT ON ("normalized_term") "normalized_term", "term", "part_of_speech"
FROM "words"
ORDER BY "normalized_term", "id"
ON CONFLICT DO NOTHING;
--> statement-breakpoint
-- Quiz sentences were always generated by AI, so they move to the shared pool.
INSERT INTO "dictionary_quiz_sentences" ("normalized_term", "sentence", "distractors", "created_at")
SELECT w."normalized_term", q."sentence", q."distractors", q."created_at"
FROM "quiz_sentences" q
JOIN "words" w ON w."id" = q."word_id"
ORDER BY q."id";
--> statement-breakpoint
-- Keep each word's rotation history.
INSERT INTO "quiz_sentence_views" ("word_id", "sentence_id", "times_used", "last_used_at")
SELECT w."id", d."id", q."times_used", q."last_used_at"
FROM "quiz_sentences" q
JOIN "words" w ON w."id" = q."word_id"
JOIN "dictionary_quiz_sentences" d
  ON d."normalized_term" = w."normalized_term" AND d."sentence" = q."sentence"
WHERE q."times_used" > 0
ON CONFLICT DO NOTHING;
